{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room for two people by placing refreshments on surfaces and positioning entertainment control accessibly.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_item",
        "entity_kind": "OBJECT",
        "function": "A drink or snack for consumption.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup", "bottle", "plate"],
        "required_properties": ["holds_consumable", "portable"]
      },
      {
        "id": "surface_for_refreshments",
        "entity_kind": "REGION",
        "function": "A flat surface to hold the refreshment item.",
        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "side_table", "desk"],
        "required_properties": ["flat", "stable", "supportive"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Device to operate the television or audio system.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["remote_control", "switch", "panel"],
        "required_properties": ["activates_media"]
      },
      {
        "id": "accessible_location",
        "entity_kind": "REGION",
        "function": "A location near seating where the entertainment control can be reached.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "floor", "shelf"],
        "required_properties": ["reachable", "near_seating"]
      },
      {
        "id": "seating_area",
        "entity_kind": "FIXED_TARGET",
        "function": "A place for a person to sit and watch television.",
        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": ["chair", "sofa", "bench"],
        "required_properties": ["supportive", "facing_tv"]
      }
    ],
    "functional_relations": [
      {
        "id": "r1",
        "relation": "is_on",
        "participant_roles": ["refreshment_item", "surface_for_refreshments"],
        "required": true
      },
      {
        "id": "r2",
        "relation": "is_on",
        "participant_roles": ["entertainment_control", "accessible_location"],
        "required": true
      },
      {
        "id": "r3",
        "relation": "is_near",
        "participant_roles": ["accessible_location", "seating_area"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "op1",
        "operation": "place",
        "participant_roles": ["refreshment_item", "surface_for_refreshments"],
        "operation_count": 2
      },
      {
        "id": "op2",
        "operation": "place",
        "participant_roles": ["entertainment_control", "accessible_location"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_item": [
        {"label": "red_cup", "visual_description": "Red cup on foreground desk"},
        {"label": "white_plate", "visual_description": "White plate on foreground desk"}
      ],
      "surface_for_refreshments": [
        {"label": "coffee_table", "visual_description": "Central green-topped table"},
        {"label": "side_table_left", "visual_description": "Wooden side table next to left chair"},
        {"label": "side_table_right", "visual_description": "Wooden side table next to right chair"},
        {"label": "console_table", "visual_description": "Table under the TV"},
        {"label": "foreground_desk", "visual_description": "Wooden desk in foreground"}
      ],
      "entertainment_control": [
        {"label": "black_remote", "visual_description": "Black remote on foreground desk"}
      ],
      "accessible_location": [
        {"label": "coffee_table", "visual_description": "Central table within reach"},
        {"label": "console_table", "visual_description": "Table under TV within reach"},
        {"label": "foreground_desk", "visual_description": "Foreground desk within reach"}
      ],
      "seating_area": [
        {"label": "armchair_left", "visual_description": "Armchair facing TV on left"},
        {"label": "armchair_right", "visual_description": "Armchair facing TV on right"}
      ]
    },
    "inspectable_regions": [
      {
        "id": "foreground_desk_storage",
        "label": "foreground_desk",
        "visual_description": "Wooden desk with knobs/handles suggesting drawers",
        "reason": "Likely contains storage compartments that could hide items or equipment."
      }
    ],
    "inspection_order": [
      "surface_for_refreshments",
      "accessible_location"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
  }
